css:
body {
	margin: 0;
	font-family: sans-serif;
}

.page.mk-o12b04 {
				padding: 24px;
				background: #f8f9fa;
			}
			.heading.mk-o12b04 {
				font-size: 26px;
				font-weight: 700;
				color: #212529;
			}
			.tasks.mk-o12b04 {
				margin: 16px 0 0;
				padding: 0;
				list-style: none;
			}
			.task.mk-o12b04 {
				display: flex;
				flex-direction: column;
				gap: 8px;
				margin-top: 8px;
				padding: 12px 16px;
				border: 1px solid #ced4da;
				border-radius: 10px;
				background: #ffffff;
			}
			.name.mk-o12b04 {
				font-size: 17px;
				color: #212529;
			}
			.done.mk-o12b04 {
				align-self: flex-start;
				padding: 2px 10px;
				border-radius: 999px;
				background: #d8f3dc;
				color: #1b4332;
				font-size: 13px;
			}
			.finish.mk-o12b04 {
				display: block;
				width: 100%;
				padding: 14px 16px;
				border: 2px solid #264653;
				border-radius: 10px;
				background: #e9f5f9;
				color: #264653;
				font-family: inherit;
				font-size: 17px;
				text-align: left;
			}
			.action.mk-o12b04 {
				display: block;
				width: 100%;
				margin-top: 12px;
				padding: 10px 16px;
				border: 2px solid #264653;
				border-radius: 10px;
				background: #ffffff;
				color: #264653;
				font-family: inherit;
				font-size: 17px;
				text-align: left;
			}
			.footer.mk-o12b04 {
				margin-top: 24px;
				padding-top: 12px;
				border-top: 1px solid #adb5bd;
				color: #495057;
				font-size: 15px;
			}
